import React, { useState, useEffect } from 'react';
import { IoIosClose, IoMdTrash } from "react-icons/io";
import { FaUpload, FaEdit, FaInfoCircle, FaFileAlt, FaBox, FaCog, FaCalculator, FaSave } from "react-icons/fa";
import uploadImage from '../helpers/uploadImage';
import SummaryApi from '../common';
import { toast } from 'react-toastify';
import DynamicProductSpecifications from './DynamicProductSpecifications';
import useCategories from '../hooks/useCategories';

const AdminEditProduct = ({
    onClose,
    productData,
    fetchdata
}) => {
    // Hook para obtener categorías dinámicamente
    const { 
        getSubcategoriesByCategory,
        getCategoriesForSelect
    } = useCategories();
    
    const [data, setData] = useState({
        // Datos básicos del producto
        productName: "",
        brandName: "",
        category: "",
        subcategory: "",
        productImage: [],
        documentationLink: "",
        description: "",
        price: "",
        sellingPrice: "",
        stock: 0,
        isVipOffer: false,
        codigo: "",
    });
    
    const [openFullScreenImage, setOpenFullScreenImage] = useState(false);
    const [fullScreenImage, setFullScreenImage] = useState("");
    const [currentExchangeRate, setCurrentExchangeRate] = useState(7300);
    const [isLoadingExchangeRate, setIsLoadingExchangeRate] = useState(false);
    
    // Efecto para cargar todos los campos del producto desde productData
    useEffect(() => {
        if (productData && Object.keys(productData).length > 0) {
            console.log('🔍 Cargando datos del producto:', productData);
            console.log('🔍 Campos financieros del producto:', {
                productName: productData.productName,
                sellingPrice: productData.sellingPrice,
                price: productData.price,
                purchasePriceUSD: productData.purchasePriceUSD,
                exchangeRate: productData.exchangeRate,
                deliveryCost: productData.deliveryCost,
                profitMargin: productData.profitMargin,
                profitAmount: productData.profitAmount,
                purchasePrice: productData.purchasePrice
            });
            
            const newData = {
                // Campos básicos
                productName: productData.productName || "",
                brandName: productData.brandName || "",
                category: productData.category || "",
                subcategory: productData.subcategory || "",
                productImage: productData.productImage || [],
                documentationLink: productData.documentationLink || "",
                description: productData.description || "",
                codigo: productData.codigo || "",
                stock: productData.stock || 0,
                isVipOffer: productData.isVipOffer || false,
                
                // Campos financieros - con valores por defecto si no existen
                price: productData.price || 0,
                sellingPrice: productData.sellingPrice || 0,
                purchasePriceUSD: productData.purchasePriceUSD || 0,
                exchangeRate: productData.exchangeRate || 7300,
                deliveryCost: productData.deliveryCost || 0,
                profitMargin: productData.profitMargin || 30,
                profitAmount: productData.profitAmount || 0,
                purchasePrice: productData.purchasePrice || 0,
                // Campos adicionales que podrían estar en el producto
                loanInterest: productData.loanInterest || 0,
                lastUpdatedFinance: productData.lastUpdatedFinance || null,
                
                // Incluir TODOS los campos adicionales del productData (especificaciones, etc.)
                ...Object.keys(productData).reduce((acc, key) => {
                    if (!acc.hasOwnProperty(key)) {
                        acc[key] = productData[key];
                    }
                    return acc;
                }, {})
            };
            
            console.log('🔍 Datos finales a cargar:', newData);
            setData(newData);
        } else {
            console.log('⚠️ No hay productData o está vacío:', productData);
        }
    }, [productData]);

    // Efecto para obtener el tipo de cambio actual
    useEffect(() => {
        fetchCurrentExchangeRate();
    }, []);

    // Función para obtener el tipo de cambio actual
    const fetchCurrentExchangeRate = async () => {
        try {
            setIsLoadingExchangeRate(true);
            const response = await fetch(SummaryApi.exchangeRate.current.url);
            const data = await response.json();
            if (data.success) {
                setCurrentExchangeRate(data.data.rate);
                // Si el producto no tiene exchangeRate, usar el actual
                if (!data.exchangeRate) {
                    setData(prev => ({
                        ...prev,
                        exchangeRate: data.data.rate
                    }));
                }
            }
        } catch (error) {
            console.error('Error obteniendo tipo de cambio:', error);
            toast.error('Error al obtener el tipo de cambio actual');
        } finally {
            setIsLoadingExchangeRate(false);
        }
    };

    // Función para calcular el precio sugerido
    const calculateSuggestedPrice = (productData) => {
        const purchaseUSD = Number(productData.purchasePriceUSD) || 0;
        const exchange = Number(productData.exchangeRate) || currentExchangeRate;
        const interest = Number(productData.loanInterest) || 15;
        const delivery = Number(productData.deliveryCost) || 10000;
        const margin = Number(productData.profitMargin) || 30;
        
        if (purchaseUSD === 0) return 0;
        
        const purchasePYG = purchaseUSD * exchange;
        const interestAmount = purchasePYG * (interest / 100);
        const totalCost = purchasePYG + interestAmount + delivery;
        const suggestedPrice = totalCost * (1 + margin / 100);
        
        return Math.round(suggestedPrice);
    };

    // Función para calcular el precio de compra en PYG
    const calculatePurchasePricePYG = (purchaseUSD, exchangeRate) => {
        return Math.round((Number(purchaseUSD) || 0) * (Number(exchangeRate) || currentExchangeRate));
    };

    const handleOnChange = (e) => {
        const { name, value } = e.target;
        setData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleImageUpload = async (e) => {
        const files = Array.from(e.target.files);
        if (files.length === 0) return;

        try {
            const uploadPromises = files.map(file => uploadImage(file));
            const uploadedImages = await Promise.all(uploadPromises);
            
                setData(prev => ({
                    ...prev,
                productImage: [...prev.productImage, ...uploadedImages]
                }));
            
            toast.success(`${uploadedImages.length} imagen(es) subida(s) exitosamente`);
        } catch (error) {
            console.error('Error uploading images:', error);
            toast.error('Error al subir las imágenes');
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        try {
            // ✅ Asegurar que ambos campos de precio tengan el mismo valor
            const productDataToSend = {
                ...data,
                price: data.sellingPrice, // El modelo requiere 'price'
                sellingPrice: data.sellingPrice // Mantener 'sellingPrice' para compatibilidad
            };

            console.log('🔧 AdminEditProduct - Enviando datos:', productDataToSend);

            const response = await SummaryApi.updateProduct(productDataToSend);
            
            if (response.status === 200) {
                toast.success('Producto actualizado exitosamente');
                fetchdata(); // Recargar la lista de productos
                onClose();
            } else {
                toast.error('Error al actualizar el producto');
            }
        } catch (error) {
            console.error('Error updating product:', error);
            toast.error('Error al actualizar el producto');
        }
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-7xl h-[95vh] flex flex-col">
                {/* Header */}
                <div className="flex justify-between items-center p-4 border-b border-gray-200 bg-gradient-to-r from-blue-50 to-indigo-50">
                    <h2 className="text-xl font-bold text-gray-800 flex items-center">
                        <FaEdit className="mr-2 text-blue-600" />
                        Editar Producto
                    </h2>
                    <button 
                        onClick={onClose}
                        className="text-2xl text-gray-500 hover:text-gray-700 transition-colors"
                    >
                        <IoIosClose />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-4">
                    <form onSubmit={handleSubmit} className="space-y-6">
                        
                        {/* Grid de 3 columnas principales */}
                        <div className="grid grid-cols-3 gap-6">
                            
                            {/* COLUMNA 1: Información del Producto */}
                            <div className="space-y-6">
                                {/* Sección: Datos Básicos */}
                                <div className="bg-gradient-to-br from-blue-50 to-blue-100 p-5 rounded-xl border border-blue-200">
                                    <div className="flex items-center mb-4 pb-3 border-b border-blue-300">
                                        <FaInfoCircle className="mr-3 text-blue-600 text-xl" />
                                        <h3 className="text-lg font-bold text-blue-800">Información del Producto</h3>
                                    </div>
                                    
                                    <div className="space-y-4">
                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Nombre del Producto *
                            </label>
                            <input
                                                type="text"
                                                name="productName"
                                value={data.productName}
                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-blue-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white transition-all"
                                required
                            />
                        </div>

                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Marca *
                            </label>
                            <input
                                                type="text"
                                                name="brandName"
                                value={data.brandName}
                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-blue-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white transition-all"
                                required
                            />
                        </div>

                                        <div className="grid grid-cols-2 gap-3">
                        <div>
                                                <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                    Categoría *
                            </label>
                            <select
                                                    name="category"
                                value={data.category}
                                onChange={(e) => {
                                                        setData({...data, category: e.target.value, subcategory: ""});
                                }}
                                                    className="w-full p-3 border-2 border-blue-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white transition-all"
                                required
                                                >
                                                    <option value="">Seleccionar</option>
                                                    {getCategoriesForSelect().map(cat => (
                                                        <option key={cat.value} value={cat.value}>
                                                            {cat.label}
                                </option>
                                ))}
                            </select>
                        </div>

                            <div>
                                                <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                    Subcategoría *
                                </label>
                                <select
                                                    name="subcategory"
                                    value={data.subcategory}
                                    onChange={handleOnChange}
                                                    className="w-full p-3 border-2 border-blue-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white transition-all disabled:bg-gray-100"
                                    required
                                                    disabled={!data.category}
                                                >
                                                    <option value="">Seleccionar</option>
                                                    {getSubcategoriesByCategory(data.category).map(sub => (
                                                        <option key={sub.value} value={sub.value}>
                                                            {sub.label}
                                    </option>
                                    ))}
                                </select>
                            </div>
                                        </div>

                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Código del Producto
                            </label>
                            <input
                                                type="text"
                                                name="codigo"
                                                value={data.codigo}
                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-blue-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white transition-all"
                                                placeholder="Ej: INF-0001"
                            />
                        </div>
                    </div>
                                </div>

                                {/* Sección: Descripción */}
                                <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-5 rounded-xl border border-purple-200">
                                    <div className="flex items-center mb-4 pb-3 border-b border-purple-300">
                                        <FaFileAlt className="mr-3 text-purple-600 text-xl" />
                                        <h3 className="text-lg font-bold text-purple-800">Descripción</h3>
                                    </div>
                                    
                                    <div className="space-y-4">
                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Descripción del Producto *
                            </label>
                            <textarea
                                name="description"
                                value={data.description}
                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-purple-200 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 bg-white transition-all resize-none"
                                                rows="6"
                                required
                            />
                        </div>

                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Enlace de Documentación
                            </label>
                            <input
                                                type="url"
                                name="documentationLink"
                                value={data.documentationLink}
                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-purple-200 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 bg-white transition-all"
                                                placeholder="https://..."
                                            />
                                        </div>
                                    </div>
                                </div>

                                {/* Sección: Inventario */}
                                <div className="bg-gradient-to-br from-green-50 to-green-100 p-5 rounded-xl border border-green-200">
                                    <div className="flex items-center mb-4 pb-3 border-b border-green-300">
                                        <FaBox className="mr-3 text-green-600 text-xl" />
                                        <h3 className="text-lg font-bold text-green-800">Inventario</h3>
                                    </div>
                                    
                                    <div className="space-y-4">
                                <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Stock Disponible
                                </label>
                                <input
                                    type="number"
                                    name="stock"
                                    value={data.stock}
                                    onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-green-200 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 bg-white transition-all"
                                    min="0"
                                />
                                </div>

                                        <div className="flex items-center p-3 bg-white rounded-lg border-2 border-green-200">
                                <input
                                    type="checkbox"
                                    id="isVipOffer"
                                    checked={data.isVipOffer}
                                                onChange={(e) => setData({...data, isVipOffer: e.target.checked})}
                                                className="w-5 h-5 text-green-600 bg-gray-100 border-gray-300 rounded focus:ring-green-500"
                                />
                                            <label htmlFor="isVipOffer" className="ml-3 text-sm font-semibold text-gray-700">
                                                Oferta VIP
                                </label>
                                </div>
                                    </div>
                                </div>
                            </div>

                            {/* COLUMNA 2: Especificaciones Técnicas */}
                            <div className="space-y-6">
                                <div className="bg-gradient-to-br from-orange-50 to-orange-100 p-5 rounded-xl border border-orange-200 h-full">
                                    <div className="flex items-center mb-4 pb-3 border-b border-orange-300">
                                        <FaCog className="mr-3 text-orange-600 text-xl" />
                                        <h3 className="text-lg font-bold text-orange-800">Especificaciones Técnicas</h3>
                                    </div>
                                    
                                    <div className="space-y-4">
                                        <DynamicProductSpecifications
                                            category={data.category}
                                            subcategory={data.subcategory}
                                            specifications={data}
                                            onSpecificationsChange={(specs) => {
                                                console.log('🔧 AdminEditProduct - Especificaciones cambiadas:', specs);
                                                setData(prev => ({ ...prev, ...specs }));
                                            }}
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* COLUMNA 3: Precios y Finanzas */}
                            <div className="space-y-6">
                                <div className="bg-gradient-to-br from-indigo-50 to-indigo-100 p-5 rounded-xl border border-indigo-200 h-full">
                                    <div className="flex items-center mb-4 pb-3 border-b border-indigo-300">
                                        <FaCalculator className="mr-3 text-indigo-600 text-xl" />
                                        <h3 className="text-lg font-bold text-indigo-800">Precios y Finanzas</h3>
                                    </div>
                                    
                                    <div className="space-y-4">
                                        {/* Precio en USD */}
                                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Precio de Compra (USD)
                                            </label>
                                            <input
                                                type="number"
                                                name="purchasePriceUSD"
                                                value={data.purchasePriceUSD || ''}
                                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-white transition-all"
                                                placeholder="Ej: 390"
                                                step="0.01"
                                                min="0"
                                            />
                                        </div>

                                        {/* Tipo de Cambio - MOSTRAR VALOR ACTUAL DE LA BD */}
                                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Tipo de Cambio (USD/PYG)
                                            </label>
                                            <div className="relative">
                                                <input
                                                    type="number"
                                                    name="exchangeRate"
                                                    value={data.exchangeRate || currentExchangeRate}
                                                    onChange={handleOnChange}
                                                    className="w-full p-3 border-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-white transition-all"
                                                    placeholder="Ej: 7600"
                                                    step="1"
                                                    min="0"
                                                />
                                                {isLoadingExchangeRate && (
                                                    <div className="absolute right-3 top-1/2 transform -translate-y-1/2">
                                                        <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-indigo-600"></div>
                                                    </div>
                                                )}
                                            </div>
                                            <p className='text-xs text-gray-500 mt-1'>
                                                Tipo de cambio actual: {currentExchangeRate.toLocaleString()} Gs
                                            </p>
                                        </div>

                                        {/* Precio de Compra PYG - Calculado automáticamente */}
                                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Precio de Compra (PYG)
                                            </label>
                                            <input
                                                type="number"
                                                value={calculatePurchasePricePYG(data.purchasePriceUSD, data.exchangeRate)}
                                                disabled
                                                className='w-full p-3 border-2 border-gray-200 rounded-lg bg-gray-100 text-gray-600'
                                                placeholder="Calculado automáticamente"
                                            />
                                        </div>

                                        {/* Interés sobre Préstamo */}
                                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Interés sobre Préstamo (%)
                                            </label>
                                            <input
                                                type="number"
                                                name="loanInterest"
                                                value={data.loanInterest || ''}
                                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-white transition-all"
                                                placeholder="0"
                                                step="0.01"
                                                min="0"
                                                max="100"
                                            />
                                        </div>

                                        {/* Costo de Envío */}
                                <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Costo de Envío (PYG)
                                    </label>
                                            <input
                                                type="number"
                                                name="deliveryCost"
                                                value={data.deliveryCost || ''}
                                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-white transition-all"
                                                placeholder="0"
                                                step="1"
                                                min="0"
                                            />
                                                </div>

                                        {/* Margen de Ganancia */}
                                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Margen de Ganancia (%)
                                            </label>
                                                <input 
                                                type="number"
                                                name="profitMargin"
                                                value={data.profitMargin || ''}
                                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-white transition-all"
                                                placeholder="30"
                                                step="0.01"
                                                min="0"
                                                />
                                            </div>

                                        {/* Precio de Venta Sugerido - Calculado */}
                                        <div className='col-span-2'>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Precio de Venta Sugerido
                                            </label>
                                            <div className='p-3 bg-blue-50 rounded-lg border-2 border-blue-200'>
                                                <div className="flex items-center justify-between">
                                                    <div>
                                                        <p className='text-xl font-bold text-blue-600'>
                                                            {calculateSuggestedPrice(data).toLocaleString()} Gs
                                                        </p>
                                                        <p className='text-xs text-gray-600 mt-1'>
                                                            Basado en cálculos automáticos
                                                        </p>
                                                    </div>
                                                    <button
                                                        type="button"
                                                        onClick={() => {
                                                            const suggestedPrice = calculateSuggestedPrice(data);
                                                            setData(prev => ({
                                                                ...prev,
                                                                sellingPrice: suggestedPrice
                                                            }));
                                                        }}
                                                        className="px-3 py-1 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700 transition-colors"
                                                    >
                                                        Usar Precio
                                                    </button>
                                                </div>
                                            </div>
                                        </div>

                                        {/* Precio de Venta Manual */}
                                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Precio de Venta Final (PYG)
                                            </label>
                                            <input
                                                type="number"
                                                name="sellingPrice"
                                                value={data.sellingPrice || ''}
                                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-white transition-all"
                                                placeholder="0"
                                                step="1"
                                                min="0"
                                            />
                                            <p className='text-xs text-gray-500 mt-1'>
                                                Puede ajustar manualmente el precio sugerido
                                            </p>
                                        </div>

                                        {/* Precio Anterior */}
                                        <div>
                                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                Precio Anterior (PYG)
                                    </label>
                                            <input
                                                type="number"
                                                name="price"
                                                value={data.price || ''}
                                                onChange={handleOnChange}
                                                className="w-full p-3 border-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-white transition-all"
                                                placeholder="0"
                                                step="1"
                                                min="0"
                                            />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Sección de Imágenes - Ocupa todo el ancho */}
                        <div className="bg-gradient-to-br from-gray-50 to-gray-100 p-5 rounded-xl border border-gray-200">
                            <div className="flex items-center mb-4 pb-3 border-b border-gray-300">
                                <FaUpload className="mr-3 text-gray-600 text-xl" />
                                <h3 className="text-lg font-bold text-gray-800">Gestión de Imágenes</h3>
                            </div>
                            
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                                {data.productImage && data.productImage.map((image, index) => (
                                    <div key={index} className="relative group">
                                        <img
                                            src={image}
                                            alt={`Product ${index + 1}`}
                                            className="w-full h-32 object-cover rounded-lg border-2 border-gray-200 hover:border-blue-500 transition-all cursor-pointer"
                                                    onClick={() => {
                                                setFullScreenImage(image);
                                                        setOpenFullScreenImage(true);
                                                    }}
                                                />
                                                <button
                                                    type="button"
                                            onClick={() => {
                                                const newImages = data.productImage.filter((_, i) => i !== index);
                                                setData({...data, productImage: newImages});
                                            }}
                                            className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 hover:bg-red-600 transition-colors opacity-0 group-hover:opacity-100"
                                        >
                                            <IoMdTrash className="w-4 h-4" />
                                                </button>
                                    </div>
                                ))}
                                
                                {/* Botón para agregar nueva imagen */}
                                <div className="border-2 border-dashed border-gray-300 rounded-lg p-4 flex flex-col items-center justify-center hover:border-blue-500 transition-colors cursor-pointer">
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleImageUpload}
                                        className="hidden"
                                        id="image-upload"
                                        multiple
                                    />
                                    <label htmlFor="image-upload" className="cursor-pointer">
                                        <FaUpload className="w-8 h-8 text-gray-400 mb-2" />
                                        <span className="text-sm text-gray-600">Agregar Imagen</span>
                                    </label>
                                </div>
                            </div>
                                </div>

                        {/* Botones de acción */}
                        <div className="flex justify-end space-x-4 pt-6 border-t-2 border-gray-200">
                            <button
                                type="button"
                                onClick={onClose}
                                className="px-8 py-3 text-gray-600 bg-gray-100 hover:bg-gray-200 rounded-lg transition-colors font-semibold"
                            >
                                Cancelar
                            </button>
                                <button 
                                    type="submit" 
                                className="px-8 py-3 bg-blue-600 text-white hover:bg-blue-700 rounded-lg transition-colors flex items-center font-semibold"
                                >
                                <FaSave className="mr-2" />
                                Guardar Cambios
                                </button>
                            </div>
                        </form>
                </div>
                    </div>
        
            {/* Modal de imagen en pantalla completa */}
                    {openFullScreenImage && (
                <div className="fixed inset-0 bg-black bg-opacity-90 z-[60] flex justify-center items-center">
                    <div className="relative max-w-4xl max-h-full p-4">
                        <button
                            onClick={() => setOpenFullScreenImage(false)}
                            className="absolute top-2 right-2 text-white text-3xl hover:text-gray-300 z-10"
                        >
                            <IoIosClose />
                        </button>
                        <img
                            src={fullScreenImage}
                            alt="Full screen"
                            className="max-w-full max-h-full object-contain"
                        />
                    </div>
                </div>
            )}
                </div>
            );
        };
        
        export default AdminEditProduct;