// frontend/src/pages/NewProductPage.js - PÁGINA DEDICADA PARA CARGA DE PRODUCTOS
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import DynamicProductSpecifications from '../components/DynamicProductSpecifications';
import SummaryApi from '../common';
import { 
  FaUpload, 
  FaSave, 
  FaTimes, 
  FaImage, 
  FaFileAlt, 
  FaDollarSign,
  FaBox,
  FaInfoCircle,
  FaExclamationTriangle,
  FaCopy,
  FaEye,
  FaEyeSlash,
  FaArrowLeft,
  FaSpinner
} from "react-icons/fa";
import useCategories from '../hooks/useCategories';
import uploadImage from '../helpers/uploadImage';
import DisplayImage from '../components/DisplayImage';
import { toast } from 'react-toastify';
import FinancialCalculator from '../components/FinancialCalculator';

const NewProductPage = () => {
  const navigate = useNavigate();
  
  // Hook para obtener categorías dinámicamente
  const { 
    getSubcategoriesByCategory,
    getCategoriesForSelect
  } = useCategories();

  const [data, setData] = useState({
    productName: "",
    brandName: "",
    category: "",
    subcategory: "",
    productImage: [],
    documentationLink: "",
    description: "",
    price: "",
    sellingPrice: "",
    stock: 0,
    isVipOffer: false,
    codigo: "",
    // Campos financieros
    purchasePriceUSD: 0,
    exchangeRate: 7300,
    loanInterest: 0,
    deliveryCost: 0,
    profitMargin: 0,
    profitAmount: 0,
    // Especificaciones dinámicas
    specifications: {}
  });

  const [loading, setLoading] = useState(false);
  const [openFullScreenImage, setOpenFullScreenImage] = useState(false);
  const [fullScreenImage, setFullScreenImage] = useState("");
  const [activeTab, setActiveTab] = useState('basic');
  const [showPreview, setShowPreview] = useState(false);
  const [validationErrors, setValidationErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Calcular ganancias automáticamente
  useEffect(() => {
    const purchasePriceUSD = Number(data.purchasePriceUSD) || 0;
    const exchangeRate = Number(data.exchangeRate) || 7300;
    const loanInterest = Number(data.loanInterest) || 0;
    const deliveryCost = Number(data.deliveryCost) || 0;
    const sellingPrice = Number(data.sellingPrice) || 0;

    const purchasePricePYG = purchasePriceUSD * exchangeRate;
    const totalCost = purchasePricePYG + loanInterest + deliveryCost;
    const profitAmount = sellingPrice - totalCost;
    const profitMargin = sellingPrice > 0 ? (profitAmount / sellingPrice) * 100 : 0;

    setData(prev => ({
      ...prev,
      profitAmount: profitAmount,
      profitMargin: profitMargin
    }));
  }, [data.purchasePriceUSD, data.exchangeRate, data.loanInterest, data.deliveryCost, data.sellingPrice]);

  const handleOnChange = (e) => {
    const { name, value, type, checked } = e.target;
    setData((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : (type === 'number' ? Number(value) : value),
    }));

    // Limpiar errores de validación cuando el usuario escribe
    if (validationErrors[name]) {
      setValidationErrors(prev => ({
        ...prev,
        [name]: null
      }));
    }
  };

  const handleSpecificationsChange = (specs) => {
    setData(prev => ({ ...prev, specifications: specs }));
  };

  const validateForm = () => {
    const errors = {};

    if (!data.productName.trim()) errors.productName = 'El nombre del producto es requerido';
    if (!data.brandName.trim()) errors.brandName = 'La marca es requerida';
    if (!data.category) errors.category = 'La categoría es requerida';
    if (!data.subcategory) errors.subcategory = 'La subcategoría es requerida';
    if (!data.description.trim()) errors.description = 'La descripción es requerida';
    if (!data.sellingPrice || data.sellingPrice <= 0) errors.sellingPrice = 'El precio de venta debe ser mayor a 0';
    if (!data.codigo.trim()) errors.codigo = 'El código del producto es requerido';

    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleUploadProduct = async (e) => {
    const files = Array.from(e.target.files);
    if (files.length === 0) return;

    setLoading(true);
    const uploadPromises = [];
    const maxImages = 10;
    const remainingSlots = maxImages - data.productImage.length;

    if (files.length + data.productImage.length > maxImages) {
      toast.warning(`Solo se pueden cargar hasta ${maxImages} imágenes en total`);
    }

    const filesToUpload = files.slice(0, remainingSlots);

    try {
      for (const file of filesToUpload) {
        if (file.size > 5 * 1024 * 1024) {
          toast.error(`La imagen ${file.name} excede el límite de 5MB`);
          continue;
        }

        if (!file.type.startsWith('image/')) {
          toast.error(`El archivo ${file.name} no es una imagen válida`);
          continue;
        }

        const uploadPromise = uploadImage(file)
          .then(response => response.url)
          .catch(error => {
            console.error(`Error al cargar ${file.name}:`, error);
            return null;
          });

        uploadPromises.push(uploadPromise);
      }

      const uploadedUrls = await Promise.all(uploadPromises);
      const validUrls = uploadedUrls.filter(url => url !== null);

      if (validUrls.length > 0) {
        setData(prev => ({
          ...prev,
          productImage: [...prev.productImage, ...validUrls]
        }));
        toast.success(`${validUrls.length} ${validUrls.length === 1 ? 'imagen cargada' : 'imágenes cargadas'} exitosamente`);
      }
    } catch (error) {
      console.error('Error al cargar las imágenes:', error);
      toast.error('Error al cargar las imágenes');
    } finally {
      setLoading(false);
    }
  };

  const handleRemoveImage = (indexToRemove) => {
    setData(prev => ({
      ...prev,
      productImage: prev.productImage.filter((_, index) => index !== indexToRemove)
    }));
    toast.success('Imagen eliminada');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!validateForm()) {
      toast.error('Por favor, corrige los errores en el formulario');
      return;
    }

    setIsSubmitting(true);
    try {
      // ✅ Asegurar que ambos campos de precio tengan el mismo valor
      const productData = {
        ...data,
        price: data.sellingPrice, // El modelo requiere 'price'
        sellingPrice: data.sellingPrice // Mantener 'sellingPrice' para compatibilidad
      };

      const response = await fetch(SummaryApi.uploadProduct.url, {
        method: SummaryApi.uploadProduct.method,
        headers: {
          "Content-Type": "application/json"
        },
        credentials: 'include',
        body: JSON.stringify(productData)
      });

      const result = await response.json();

      if (result.success) {
        toast.success("Producto cargado exitosamente");
        navigate('/panel-admin/productos');
      } else {
        toast.error(result.message || "Error al cargar el producto");
      }
    } catch (error) {
      console.error('Error:', error);
      toast.error("Error de conexión");
    } finally {
      setIsSubmitting(false);
    }
  };

  const generateProductCode = () => {
    const categoryCode = data.category ? data.category.substring(0, 3).toUpperCase() : 'PRO';
    const timestamp = Date.now().toString().slice(-6);
    const randomCode = Math.random().toString(36).substring(2, 5).toUpperCase();
    return `${categoryCode}-${timestamp}-${randomCode}`;
  };

  const tabs = [
    { id: 'basic', label: 'Información Básica', icon: <FaInfoCircle className="w-4 h-4" /> },
    { id: 'images', label: 'Imágenes', icon: <FaImage className="w-4 h-4" /> },
    { id: 'pricing', label: 'Precios y Finanzas', icon: <FaDollarSign className="w-4 h-4" /> },
    { id: 'inventory', label: 'Inventario', icon: <FaBox className="w-4 h-4" /> },
    { id: 'specs', label: 'Especificaciones', icon: <FaFileAlt className="w-4 h-4" /> }
  ];

  const InputField = ({ label, name, type = "text", required = false, placeholder = "", className = "", ...props }) => (
    <div className={className}>
      <label className="block text-sm font-medium text-gray-700 mb-1">
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      <input
        type={type}
        name={name}
        value={data[name]}
        onChange={handleOnChange}
        placeholder={placeholder}
        className={`w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
          validationErrors[name] ? 'border-red-500' : 'border-gray-300'
        }`}
        {...props}
      />
      {validationErrors[name] && (
        <p className="mt-1 text-sm text-red-600 flex items-center">
          <FaExclamationTriangle className="w-3 h-3 mr-1" />
          {validationErrors[name]}
        </p>
      )}
    </div>
  );

  const SelectField = ({ label, name, required = false, options = [], className = "" }) => (
    <div className={className}>
      <label className="block text-sm font-medium text-gray-700 mb-1">
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      <select
        name={name}
        value={data[name]}
        onChange={handleOnChange}
        className={`w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
          validationErrors[name] ? 'border-red-500' : 'border-gray-300'
        }`}
      >
        <option value="">Seleccionar {label.toLowerCase()}</option>
        {options.map(option => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
      {validationErrors[name] && (
        <p className="mt-1 text-sm text-red-600 flex items-center">
          <FaExclamationTriangle className="w-3 h-3 mr-1" />
          {validationErrors[name]}
        </p>
      )}
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center py-6">
            <div className="flex items-center">
              <button
                onClick={() => navigate('/panel-admin/productos')}
                className="flex items-center text-gray-600 hover:text-gray-900 mr-4"
              >
                <FaArrowLeft className="w-4 h-4 mr-2" />
                Volver
              </button>
              <div>
                <h1 className="text-2xl font-bold text-gray-900">Nuevo Producto</h1>
                <p className="text-gray-600 mt-1">Agrega un nuevo producto al catálogo</p>
              </div>
            </div>
            
            <div className="flex items-center space-x-3">
              <button
                onClick={() => setShowPreview(!showPreview)}
                className="flex items-center px-4 py-2 text-gray-600 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
              >
                {showPreview ? <FaEyeSlash className="w-4 h-4 mr-2" /> : <FaEye className="w-4 h-4 mr-2" />}
                {showPreview ? 'Ocultar Vista Previa' : 'Vista Previa'}
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
          {/* Tabs */}
          <div className="border-b border-gray-200">
            <nav className="flex space-x-8 px-6">
              {tabs.map(tab => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`py-4 px-1 border-b-2 font-medium text-sm flex items-center space-x-2 ${
                    activeTab === tab.id
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  {tab.icon}
                  <span>{tab.label}</span>
                </button>
              ))}
            </nav>
          </div>

          <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto">
            <div className="p-6">
              {/* Tab: Información Básica */}
              {activeTab === 'basic' && (
                <div className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <InputField
                      label="Nombre del Producto"
                      name="productName"
                      required
                      placeholder="Ej: Laptop Dell Inspiron 15"
                    />
                    <InputField
                      label="Marca"
                      name="brandName"
                      required
                      placeholder="Ej: Dell"
                    />
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <SelectField
                      label="Categoría"
                      name="category"
                      required
                      options={getCategoriesForSelect()}
                    />
                    <SelectField
                      label="Subcategoría"
                      name="subcategory"
                      required
                      options={getSubcategoriesByCategory(data.category)}
                    />
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <InputField
                      label="Código del Producto"
                      name="codigo"
                      required
                      placeholder="Código único del producto"
                    />
                    <div className="flex items-end">
                      <button
                        type="button"
                        onClick={() => setData(prev => ({ ...prev, codigo: generateProductCode() }))}
                        className="flex items-center px-4 py-3 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors"
                      >
                        <FaCopy className="w-4 h-4 mr-2" />
                        Generar Código
                      </button>
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Descripción <span className="text-red-500">*</span>
                    </label>
                    <textarea
                      name="description"
                      value={data.description}
                      onChange={handleOnChange}
                      rows={4}
                      placeholder="Describe las características principales del producto..."
                      className={`w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
                        validationErrors.description ? 'border-red-500' : 'border-gray-300'
                      }`}
                    />
                    {validationErrors.description && (
                      <p className="mt-1 text-sm text-red-600 flex items-center">
                        <FaExclamationTriangle className="w-3 h-3 mr-1" />
                        {validationErrors.description}
                      </p>
                    )}
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Enlace de Documentación
                    </label>
                    <input
                      type="url"
                      name="documentationLink"
                      value={data.documentationLink}
                      onChange={handleOnChange}
                      placeholder="https://ejemplo.com/manual"
                      className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>
                </div>
              )}

              {/* Tab: Imágenes */}
              {activeTab === 'images' && (
                <div className="space-y-6">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Imágenes del Producto
                    </label>
                    <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center hover:border-gray-400 transition-colors">
                      <input
                        type="file"
                        multiple
                        accept="image/*"
                        onChange={handleUploadProduct}
                        className="hidden"
                        id="image-upload"
                        disabled={loading}
                      />
                      <label
                        htmlFor="image-upload"
                        className="cursor-pointer flex flex-col items-center"
                      >
                        {loading ? (
                          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                        ) : (
                          <>
                            <FaUpload className="w-8 h-8 text-gray-400 mb-2" />
                            <p className="text-gray-600">
                              Haz clic para cargar imágenes o arrastra archivos aquí
                            </p>
                            <p className="text-sm text-gray-500 mt-1">
                              Máximo 10 imágenes, 5MB por archivo
                            </p>
                          </>
                        )}
                      </label>
                    </div>
                  </div>

                  {/* Galería de imágenes */}
                  {data.productImage.length > 0 && (
                    <div>
                      <h3 className="text-lg font-medium text-gray-900 mb-3">
                        Imágenes Cargadas ({data.productImage.length}/10)
                      </h3>
                      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                        {data.productImage.map((image, index) => (
                          <div key={index} className="relative group">
                            <div className="aspect-square rounded-lg overflow-hidden border border-gray-200">
                              <DisplayImage
                                img={image}
                                className="w-full h-full object-cover cursor-pointer"
                                onClick={() => {
                                  setFullScreenImage(image);
                                  setOpenFullScreenImage(true);
                                }}
                              />
                            </div>
                            <button
                              type="button"
                              onClick={() => handleRemoveImage(index)}
                              className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-sm hover:bg-red-600 transition-colors"
                            >
                              <FaTimes />
                            </button>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}

              {/* Tab: Precios y Finanzas */}
              {activeTab === 'pricing' && (
                <FinancialCalculator
                  data={data}
                  onDataChange={(financialData) => {
                    setData(prev => ({
                      ...prev,
                      ...financialData
                    }));
                  }}
                  mode="create"
                />
              )}

              {/* Tab: Inventario */}
              {activeTab === 'inventory' && (
                <div className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <InputField
                      label="Stock Inicial"
                      name="stock"
                      type="number"
                      placeholder="0"
                    />
                    <div className="flex items-center space-x-3">
                      <input
                        type="checkbox"
                        name="isVipOffer"
                        checked={data.isVipOffer}
                        onChange={handleOnChange}
                        className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                      />
                      <label className="text-sm font-medium text-gray-700">
                        Oferta VIP
                      </label>
                    </div>
                  </div>

                  <div className="bg-yellow-50 p-4 rounded-lg">
                    <h4 className="text-sm font-medium text-yellow-800 mb-2">
                      Información de Inventario
                    </h4>
                    <ul className="text-sm text-yellow-700 space-y-1">
                      <li>• El stock se puede ajustar después de crear el producto</li>
                      <li>• Las ofertas VIP aparecen destacadas en el catálogo</li>
                      <li>• El sistema notificará cuando el stock esté bajo</li>
                    </ul>
                  </div>
                </div>
              )}

              {/* Tab: Especificaciones */}
              {activeTab === 'specs' && (
                <div className="space-y-6">
                  {data.category && data.subcategory ? (
                    <DynamicProductSpecifications
                      category={data.category}
                      subcategory={data.subcategory}
                      specifications={data.specifications || {}}
                      onSpecificationsChange={handleSpecificationsChange}
                    />
                  ) : (
                    <div className="text-center py-12">
                      <FaInfoCircle className="mx-auto h-12 w-12 text-gray-400" />
                      <h3 className="mt-2 text-sm font-medium text-gray-900">Selecciona Categoría y Subcategoría</h3>
                      <p className="mt-1 text-sm text-gray-500">
                        Primero debes seleccionar una categoría y subcategoría en la pestaña "Información Básica" para ver las especificaciones disponibles.
                      </p>
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Footer con botones */}
            <div className="flex justify-between items-center p-6 border-t border-gray-200 bg-gray-50">
              <div className="flex items-center space-x-4">
                <button
                  type="button"
                  onClick={() => navigate('/panel-admin/productos')}
                  className="px-6 py-2 text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
                >
                  Cancelar
                </button>
              </div>
              
              <div className="flex items-center space-x-3">
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className="flex items-center px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  {isSubmitting ? (
                    <>
                      <FaSpinner className="w-4 h-4 mr-2 animate-spin" />
                      Guardando...
                    </>
                  ) : (
                    <>
                      <FaSave className="w-4 h-4 mr-2" />
                      Crear Producto
                    </>
                  )}
                </button>
              </div>
            </div>
          </form>
        </div>
      </div>

      {/* Modal de imagen en pantalla completa */}
      {openFullScreenImage && (
        <div className="fixed inset-0 bg-black bg-opacity-75 z-[300] flex items-center justify-center p-4">
          <div className="relative max-w-4xl max-h-full">
            <button
              onClick={() => setOpenFullScreenImage(false)}
              className="absolute -top-10 right-0 text-white text-2xl hover:text-gray-300"
            >
              <FaTimes />
            </button>
            <DisplayImage
              img={fullScreenImage}
              className="max-w-full max-h-full object-contain rounded-lg"
            />
          </div>
        </div>
      )}
    </div>
  );
};

export default NewProductPage;
